def disclosure(expanded: Var[Boolean])(content: Boolean => Modifier[Div]): Div =
  div(
    content(expanded.now()),                       // markup supplied by the call site
    onClick --> { _ => expanded.update(!expanded.now()) }   // behaviour owns the transition
  )
